  "اختر مستخدماً…": "Choose a user…",
  "اختر من الأسعار المسجّلة…": "Choose from saved prices…",
  "اختر من القائمة": "Choose from the list",
  "اختر منصة لملء الاسم والكود تلقائيًا، أو أدخلهما يدويًا بالأسفل.": "Choose a platform to fill in the name and code automatically, or enter them manually below.",
  "اختر منصة معروفة (أمازون) ويتم التجهيز تلقائيًا: عميل + مخزن + بنك.": "Choose a known platform (Amazon) and it's set up automatically: customer + warehouse + bank.",
  "اختر…": "Choose…",
  "اختَر الطرف أولاً، ثم صدّر كشفه Excel أو PDF بنفس الفترة.": "Choose the party first, then export their statement to Excel or PDF for the same period.",
  "اخرج من كل الأجهزة": "Sign out of all devices",
  "ادخل بريد المستخدم (دور: client) لربطه بهذا العميل. اتركه فارغاً لإلغاء الربط.": "Enter the user's email (role: client) to link them to this customer. Leave it empty to unlink.",
  "اربط الأكواد بالأصناف": "Link codes to items",
  "اربط هذا الصنف كتنويعة تحت منتج أب — يعمل مع أي منصة (أمازون/نون/جوميا) أو بدون منصة.": "Link this item as a variant under a parent product — works with any platform (Amazon/Noon/Jumia) or none.",
  "اربطه بسجل الموظف": "Link to the employee record",
  "ارجع لشركتي": "Back to my company",
  "ارفع الفاتورة": "Upload the invoice",
  "ارفع تقرير الإزالة (Removal Order/Shipment Detail). الوحدات المُتلَفة (Disposed) تُسجَّل كخسارة مخزون عبر تسوية (مسودة) في مخزن المنصة؛ الوحدات المُرتجَعة للبائع تُعرَض للحصر فقط. لا تؤكّد التسوية لو سبق وطابقت المخزون بالدفتر (تجنبًا للتكرار).": "Upload the removal report (Removal Order/Shipment Detail). Disposed units are recorded as an inventory loss via a (draft) adjustment in the platform warehouse; units returned to the seller are listed for reference only. Don't confirm the adjustment if you already reconciled inventory against the ledger (to avoid double counting).",
  "ارفع تقرير دفتر مخزون أمازون (Inventory Ledger). نحسب الرصيد لكل SKU ونطابقه بمخزون المنصة، ثم يمكنك إنشاء تسوية لضبط الفروق.": "Upload the Amazon Inventory Ledger report. We compute the balance per SKU and match it against the platform warehouse, then you can create an adjustment to fix the differences.",
  "ارفع تقرير مرتجعات العملاء (FBA Customer Returns)، اربط الأعمدة، ثم استورد. لكل مرتجع نطابق أمر البيع وفاتورته المُرحّلة، ونُنشئ": "Upload the FBA Customer Returns report, map the columns, then import. For each return we match the sales order and its posted invoice, and create",
  "ارفع ملف CSV أو Excel من المنصة، اربط الأعمدة، ثم استورد. كل رقم طلب يصبح أمر بيع باسم عميل المنصة. المكرر يُتخطّى تلقائيًا.": "Upload a CSV or Excel file from the platform, map the columns, then import. Each order number becomes a sales order under the platform's customer. Duplicates are skipped automatically.",
  "ارفع ملف المدفوعات/التحويلات، اربط الأعمدة، ثم استورد. كل دفعة تصبح سند قبض (مسودة) باسم عميل المنصة على حسابها البنكي. أكّد السندات لترحيلها.": "Upload the payments/transfers file, map the columns, then import. Each payment becomes a (draft) receipt voucher under the platform's customer on its bank account. Confirm the vouchers to post them.",
