  "مُطفأ (الافتراضي): الأوامر تنزل بسعرها كامل ومفيش ضريبة تُرحَّل. مفعّل: تُستخرج الضريبة من السعر وتُرحَّل على «ضريبة المخرجات» — الإجمالي ما يتغيّرش في الحالتين. التغيير يسري على الأوامر الجديدة بس.": "Off (default): orders come in at their full price and no tax is posted. On: tax is extracted from the price and posted to \"Output tax\" — the total doesn't change either way. The change applies to new orders only.",
