  "يحدّد دور كل مستخدم ما يمكنه فعله. استخدم «تخصيص» لمنح أو منع صلاحيات فردية فوق الدور.": "Each user's role determines what they can do. Use \"Customize\" to grant or deny individual permissions on top of the role.",
  "يحكم حدود كل فتراتك المحاسبية والإقفال السنوي": "Governs the boundaries of all your accounting periods and the year-end close",
  "يدخل العضو بالبريد وكلمة المرور المبدئية، ويشوف الوحدات حسب دوره فقط.": "The member signs in with their email and initial password, and sees modules according to their role only.",
  "يرحّل كل مرتجع محدّد حسب حالته (التالف لا يرجع مخزون قابل للبيع)": "Posts each selected return according to its condition (damaged goods don't go back to sellable stock)",
  "يشتري": "Buys",
  "يعكس قيود التسوية المرحّلة ويعيد الأرصدة، ثم أعد الترحيل ليُبنى على مستوى كل طلب": "Reverses the posted settlement entries and restores the balances; then re-post to rebuild them per order",
  "يعمل بهدوء في الخلفية — تقدر تسيب الصفحة مفتوحة، وسيكتمل دون تحميل على السيرفر.": "Runs quietly in the background — you can leave the page open, and it completes without loading the server.",
  "يكفّي (يوم)": "Covers (days)",
  "ينشئ أوامر بيع مسودة من ملف CSV. صفوف بنفس المرجع = أمر واحد بعدة بنود.": "Creates draft sales orders from a CSV file. Rows with the same reference = one order with several lines.",
  "ينشئ أوامر شراء مسودة من ملف CSV. صفوف بنفس المرجع = أمر واحد بعدة بنود.": "Creates draft purchase orders from a CSV file. Rows with the same reference = one order with several lines.",
  "ينشئ إذن صرف مسودة لكل أمر مؤكّد بالكمية المتبقية": "Creates a draft delivery note for each confirmed order with the remaining quantity",
  "ينشئ تحويلات مخزنية مسودة من ملف CSV. صفوف بنفس المرجع = تحويل واحد بعدة بنود.": "Creates draft stock transfers from a CSV file. Rows with the same reference = one transfer with several lines.",
  "ينشئ سند قبض مسودة بقيمة المتبقّي لكل فاتورة مرحّلة عليها رصيد": "Creates a draft receipt voucher for the remaining amount of each posted invoice with a balance",
  "ينشئ فاتورة مسودة لكل إذن مؤكّد": "Creates a draft invoice for each confirmed note",
  "يُرحَّل قيد الاستبعاد: النقدية ومجمع الإهلاك مدينان، وحساب الأصل دائن، والفرق ربح أو خسارة.": "The disposal entry is posted: cash and accumulated depreciation are debited, the asset account credited, and the difference is a gain or loss.",
