  "ارفع تقرير طلبات أمازون لاستخراج أكواد SKU/ASIN غير المربوطة. لكل كود: إمّا تربطه بصنف موجود (يُقترح تلقائياً لو كوده الداخلي = SKU)، أو — لو تعمل لأول مرة — تنشئ صنفاً جديداً مباشرة (كود داخلي تلقائي P-xxxxx + اسم وسعر أمازون). زر «إنشاء أصناف جديدة للباقي» يفعلها للكل دفعة واحدة.": "Upload the Amazon orders report to extract the unlinked SKU/ASIN codes. For each code, either link it to an existing item (suggested automatically if its internal code = the SKU) or — if you're just starting — create a new item directly (automatic internal code P-xxxxx + Amazon name and price). The \"Create new items for the rest\" button does it for all of them at once.",
