  "يسحب تقارير التسويات مباشرة من أمازون — تفاصيل الطلبات + التحويلات البنكية + الرسوم/العمولات. التقارير تُصدرها أمازون كل ~أسبوعين عند إقفال فترة تسوية. الترحيل المحاسبي حسب إعداد المنصة (تلقائي أو مراجعة يدوية). إعادة السحب لا تُكرّر (منع تكرار بالمفتاح الفريد).": "Pulls the settlement reports straight from Amazon — order details + bank transfers + fees/commissions. Amazon issues the reports every ~2 weeks when a settlement period closes. Accounting posting follows the platform setting (automatic or manual review). Pulling again never duplicates (deduplicated by unique key).",
