  "مسودة فقط": "Draft only",
  "الطلب يدخل النظام كمسودة بدون تأكيد — أنت تراجع وتؤكّد كل طلب يدويًا.": "The order enters the system as an unconfirmed draft — you review and confirm each order manually.",
  "أمر بيع مؤكّد": "Confirmed sales order",
  "الطلب المشحون يُؤكَّد تلقائيًا — إذن الصرف والفاتورة عليك.": "A shipped order is confirmed automatically — the delivery note and invoice are up to you.",
  "تأكيد + إذن صرف": "Confirm + delivery note",
  "بعد التأكيد يُنشأ إذن الصرف ويُرحَّل (خصم المخزون وتكلفة البضاعة).": "After confirmation the delivery note is created and posted (stock and cost of goods deducted).",
  "الدورة كاملة حتى الفاتورة": "The full cycle through to the invoice",
  "تأكيد + صرف + فاتورة مُرحّلة (إيراد وذمم) — الوضع الافتراضي.": "Confirm + deliver + posted invoice (revenue and receivables) — the default.",
  "المنتجات": "Products",
  "سحب الكتالوج وربطه بالأصناف (حسب وضع المزامنة بالأسفل).": "Pull the catalogue and link it to items (per the sync mode below).",
  "الطلبات الجديدة أولًا بأول — وتدخل الدورة حسب «المعالجة التلقائية».": "New orders as they come in — they enter the cycle per \"Automatic processing\".",
  "قراءة كميات FBA للمقارنة في تدقيق المخزون (لا يغيّر أرصدتك).": "Read FBA quantities to compare in the inventory audit (doesn't change your balances).",
  "المدفوعات والتسويات": "Payments & settlements",
  "تقارير التسويات (المبالغ والرسوم والتحويلات البنكية).": "Settlement reports (amounts, fees and bank transfers).",
  "مرتجعات FBA تُسحب تلقائيًا وتُنشأ كمرتجع فاتورة مسودة للمراجعة.": "FBA returns are pulled automatically and created as a draft invoice return for review.",
  "أمازون يخزّن ويشحن": "Amazon stores and ships",
