  "رسوم مخزون FBA": "FBA storage fees",
  "الأساس المحاسبي": "Accounting basis",
  "أول وأهم خطوة: بداية السنة المالية (افتراضيًا 1 يناير — غيّرها لو سنتك المالية مختلفة) والعملة الأساسية (الجنيه المصري افتراضيًا). تحكم كل فتراتك المحاسبية وتقاريرك — تُقفل بعد أول عملية، فاضبطها الآن.": "The first and most important step: the fiscal year start (1 January by default — change it if your fiscal year differs) and the base currency (Egyptian pound by default). They govern all your accounting periods and reports — they lock after the first transaction, so set them now.",
  "ضبط الأساس المحاسبي": "Set the accounting basis",
  "العملة الأساسية": "Base currency",
  "بيانات الشركة": "Company details",
  "أدخل الرقم الضريبي (يظهر على فواتيرك الضريبية) مع الاسم القانوني والشعار. لست مسجّلاً ضريبيًا؟ اضغط الدائرة لتمييز الخطوة كمكتملة.": "Enter the tax number (shown on your tax invoices) with the legal name and logo. Not tax-registered? Click the circle to mark the step as done.",
  "فتح الإعدادات": "Open settings",
  "أُنشئ لك دليل قياسي كامل تلقائيًا — راجعه وعدّل ما يلزم ليطابق نشاطك.": "A complete standard chart was created for you automatically — review it and adjust what's needed to match your business.",
  "مراجعة الدليل": "Review the chart",
  "قطعة، كرتونة، كيلو… تحتاج وحدة واحدة على الأقل قبل إضافة الأصناف.": "Piece, carton, kilo… you need at least one unit before adding items.",
  "إدارة الوحدات": "Manage units",
  "أُنشئ «المستودع الرئيسي» تلقائيًا — أضف مخازن أخرى لو عندك أكثر من موقع.": "\"Main warehouse\" was created automatically — add other warehouses if you have more than one location.",
  "أضف منتجاتك: يدويًا واحدًا واحدًا، أو استيراد ملف دفعة واحدة، أو مزامنة مباشرة من أمازون.": "Add your products: one by one, by importing a file in one go, or by syncing straight from Amazon.",
  "صنف جديد": "New item",
  "استيراد ملف": "Import a file",
  "أضف عملاءك (منصات البيع تُنشئ عميلها تلقائيًا عند ربطها).": "Add your customers (sales platforms create their own customer when linked).",
  "أضف مورّديك لتسجيل المشتريات وأذون الاستلام والفواتير.": "Add your suppliers to record purchases, goods receipts and invoices.",
  "الأهم قبل أول عملية: أدخل أرصدة المخزون والعملاء والموردين والبنوك كما هي اليوم — تقدر تسحب كميات مخزونك مباشرة من أمازون. شركة جديدة بلا أرصدة؟ اضغط الدائرة لتمييزها كمكتملة.": "Most important before the first transaction: enter your inventory, customer, supplier and bank balances as they are today — you can pull your stock quantities straight from Amazon. A new company with no balances? Click the circle to mark it as done.",
  "ترقيم المستندات": "Document numbering",
  "غيّر بادئات أرقام الفواتير والأوامر (SI، SO…) لو أردت ترقيمًا خاصًا — الافتراضي جاهز.": "Change the number prefixes of invoices and orders (SI, SO…) if you want your own numbering — the default is ready.",
  "الترقيم": "Numbering",
  "ربط منصة بيع": "Connect a sales platform",
  "اربط أمازون أو أضف منصة يدوية — مبيعاتها ومدفوعاتها تتزامن أو تُستورد لعميلها ومخزنها.": "Connect Amazon or add a manual platform — its sales and payments sync or are imported to its own customer and warehouse.",
  "اربط حساب أمازون": "Connect your Amazon account",
  "من صفحة المنصات: «ربط أمازون» ووافق على الصلاحيات في Seller Central. لو الربط انتهى هتلاقيها هنا مش متعلّمة.": "From the platforms page: \"Connect Amazon\" and approve the permissions in Seller Central. If the connection expires, you'll find this step unticked here.",
  "أول مزامنة": "First sync",
  "شغّل «مزامنة الآن» من صفحة أمازون — بتجيب المنتجات والطلبات لأول مرة.": "Run \"Sync now\" from the Amazon page — it fetches the products and orders for the first time.",
  "اربط الـSKUs بالأصناف": "Link SKUs to items",
  "أي طلب فيه SKU مش معروف بيستنى في «طلبات بمنتج غير معروف» — اربطه بصنفه وهيتسجّل لوحده.": "Any order with an unknown SKU waits in \"Orders with an unknown product\" — link it to its item and it is recorded automatically.",
  "طلبات بمنتج غير معروف": "Orders with an unknown product",
  "أول تدقيق مخزون FBA": "First FBA inventory audit",
  "قارن مخزون أمازون بمخزون النظام — بعدها خطة الشحن بتشتغل على أرقام أمازون الحقيقية.": "Compare Amazon's stock with the system's — after that the shipping plan works on Amazon's real numbers.",
  "مطابقة المخزون": "Reconcile inventory",
  "استيراد كامل": "Full import",
  "اكتشاف منتجات": "Discover products",
  "تفاصيل الأصناف": "Item details",
  "الصور": "Images",
  "التسويات": "Settlements",
  "دفتر FBA": "FBA ledger",

