  "/api/v1/items — الأصناف (كود، اسم، سعر البيع، حد الطلب)": "/api/v1/items — items (code, name, selling price, reorder point)",
  "/api/v1/sales-orders — إنشاء أمر بيع مسودة (customer + lines بالـ code أو id)": "/api/v1/sales-orders — create a draft sales order (customer + lines by code or id)",
  "/api/v1/stock — الأرصدة (المتوفّر + القيمة لكل صنف)": "/api/v1/stock — balances (available + value per item)",
  "Anthropic مابتستخدمش بيانات الـAPI في تدريب موديلاتها بشكل افتراضي.": "Anthropic doesn't use API data to train its models by default.",
  "DSO — ذمم مدينة ÷ متوسط البيع اليومي": "DSO — receivables ÷ average daily sales",
  "«راكد» = لا مبيعات خلال الفترة · «بطيء» = المخزون يكفي أكثر من فترة كاملة بمعدّل البيع الحالي.": "\"Dead\" = no sales in the period · \"Slow\" = stock lasts more than a full period at the current sales rate.",
  "، ومش بيظهر تاني لأي حد ولا بيتسجّل في أي لوج، وبيتستخدم لطلبات شركتك بس. أي تغيير فيه بيتسجّل في سجل التدقيق.": ", isn't shown again to anyone or written to any log, and is used only for your company's requests. Any change to it is recorded in the audit log.",
