  "يسحب مدفوعات {0} (Payments) مباشرة عبر الـ API — تحصيل الطلبات + التحويلات البنكية + العمولات. الترحيل المحاسبي حسب إعداد المنصة (تلقائي أو مراجعة يدوية). إعادة السحب لا تُكرّر.": "Pulls {0} payments straight through the API — order collections + bank transfers + commissions. Accounting posting follows the platform setting (automatic or manual review). Pulling again never duplicates.",
