  // ── text next to values, and text on its own line ──
  "(الأستاذ يُسجَّل بـ": "(the ledger records it at",
  "(الدور:": "(role:",
  "(سعر الصرف": "(exchange rate",
  "(متبقّي": "(remaining",
  "(مدين المحفظة / دائن تعويضات المنصات 4103) يراجعه المحاسب ويرحّله — عشان ماتتكرّرش مع التسوية. التعويض العيني (وحدات) بيتعرض وترجّعه من أوامر السحب/التسويات.": "(debit the wallet / credit platform reimbursements 4103) the accountant reviews and posts it — so it isn't duplicated with the settlement. In-kind reimbursement (units) is shown and you return it from removal orders/settlements.",
  "(مع رسم لو حابب)، وبعدين اعمل لوحة وضيفه فيها.": "(with a chart if you like), then create a dashboard and add it.",
  ") في كل الصفحات": ") across all pages",
  ") — أُنشئت كأوامر مؤكّدة بلا صرف؛ وفّر المخزون ثم أعد الرفع:": ") — created as confirmed orders without issuing; get the stock in, then upload again:",
  "). التحويلات من صفوف «Transfer» في تقرير التسويات.": "). Transfers come from the \"Transfer\" rows in the settlements report.",
  ". «موروث» يتبع الدور؛ «سماح» يمنح الصلاحية فوق الدور؛ «منع» يسحبها.": ". \"Inherited\" follows the role; \"Allow\" grants the permission on top of the role; \"Deny\" removes it.",
  ". العميل بيرجّع للمنصة، والمنصة مش دايماً بتبعتهالك — فمفيش حاجة بتترحّل لحد ما تقول إيه اللي وصلك بالظبط.": ". The customer returns to the platform, and the platform doesn't always send it back to you — so nothing is posted until you say exactly what reached you.",
  "SKU غير مربوط ·": "unlinked SKUs ·",
  "SKU غير مربوط بصنف في النظام (لن يدخل التسوية). عيّنة:": "SKUs aren't linked to an item in the system (they won't enter the settlement). Sample:",
  "SKU غير مربوط:": "unlinked SKUs:",
  "· آخر مزامنة:": "· Last sync:",
