  "سيُحذف كل شيء يخص «{0}» بشكل لا يمكن التراجع عنه: المستخدمون، الفواتير، القيود، المخزون، الاشتراك، والربط بالمنصات.": "Everything belonging to “{0}” will be deleted and can't be undone: users, invoices, journal entries, stock, subscription and platform connections.",
  "حذف نهائي": "Delete permanently",
  "## الخطوة الأولى\n\nافتح **المبيعات ← أوامر البيع** ودوس «أمر جديد».\n\n![شاشة أوامر البيع](…)\n\n- اختار العميل\n- ضيف الأصناف\n\n> الأمر بيفضل مسودة لحد ما تأكّده.": "## Step one\n\nOpen **Sales → Sales orders** and click “New order”.\n\n![Sales orders screen](…)\n\n- Choose the customer\n- Add the items\n\n> The order stays a draft until you confirm it.",
  "بيرفع الـscreenshot ويحطه مكان المؤشر. يدعم العناوين (##) والقوائم (-) والغامق (**) والجداول.": "uploads the screenshot and places it at the cursor. Supports headings (##), lists (-), bold (**) and tables.",
