  "تم تصفير بيانات «{0}»": "Data of “{0}” was reset",
  "يُمسح كل الحركات في «{0}» (فواتير، أوامر، أذون، مرتجعات، قيود، حركة المخزون، التسويات، المدفوعات) بشكل لا يمكن التراجع عنه. تبقى هوية الشركة: الاسم والمستخدمون والاشتراك وربط المنصات.": "All transactions in “{0}” (invoices, orders, notes, returns, journal entries, stock movements, adjustments, payments) will be wiped and this can't be undone. The company's identity stays: name, users, subscription and platform connections.",
  "تم حذف «{0}» وكل بياناتها نهائيًا": "“{0}” and all its data were permanently deleted",
  "سيُحذف كل شيء يخص «{0}» بلا رجعة: المستخدمون، الفواتير، القيود، المخزون، الاشتراك، وربط المنصات.": "Everything belonging to “{0}” will be deleted for good: users, invoices, journal entries, stock, subscription and platform connections.",
  "{0} جيجا": "{0} GB",
  "دلوقتي تقدر ترحّل شركة شغّالة من نظامك القديم:\n\n- أرصدة العملاء والموردين\n- المخزون بتكلفته\n- أرصدة البنوك\n\nمن **الإعدادات ← الأرصدة الافتتاحية**.": "You can now migrate a running company from your old system:\n\n- Customer and supplier balances\n- Stock at cost\n- Bank balances\n\nFrom **Settings → Opening balances**.",
