  "مفتاح Anthropic API اللي بتقرا بيه الشركات فواتيرها. الميزة بتفضل مقفولة لحد ما تختار موديل.": "The Anthropic API key companies use to read their invoices. The feature stays off until you choose a model.",
  "المفتاح بيتخزن مشفّر، ومش بيرجع للمتصفح. الشركة اللي تضيف مفتاحها الخاص بتستخدمه هو ومش بتتحسب من الحد.": "The key is stored encrypted and never sent back to the browser. A company that adds its own key uses it and isn't counted against the limit.",
