  "إكسيل للمخزون، برنامج للمحاسبة، وشيت للطلبات — وكل شهر الأرقام مش بتتطابق.": "Excel for inventory, a program for accounting, and a sheet for orders — and every month the numbers don't match.",
  "مخزون موزّع على أكتر من مستودع ومنصة، ومحدش عارف الرصيد الحقيقي أو اللي قرب يخلص.": "Stock spread across several warehouses and platforms, and nobody knows the real balance or what's about to run out.",
  "مفيش صورة واضحة للربح الحقيقي بعد الشحن والخصومات والضريبة والمرتجعات.": "No clear picture of your real profit after shipping, discounts, tax and returns.",
  "آخر الشهر = كابوس تجميع أرقام يدوي وأخطاء بتكلّفك فلوس.": "Month-end = a nightmare of gathering numbers by hand, and mistakes that cost you money.",
  "محاسبة كاملة": "Full accounting",
  "قيد مزدوج حقيقي، دليل حسابات، قوائم مالية (دخل · ميزانية · ميزان مراجعة)، ومراكز تكلفة — بترحيل تلقائي من كل مستند.": "True double-entry, a chart of accounts, financial statements (income · balance sheet · trial balance) and cost centers — posted automatically from every document.",
  "مخزون دقيق": "Accurate inventory",
  "متعدد المستودعات، تكلفة بالدفعة (FIFO)، تتبّع الدفعات وتاريخ الصلاحية (FEFO)، تسويات وتحويلات، وتنبيهات النواقص والانتهاء.": "Multi-warehouse, batch costing (FIFO), batch and expiry tracking (FEFO), adjustments and transfers, and shortage and expiry alerts.",
  "دورة شراء كاملة": "Full purchasing cycle",
  "أمر شراء ← إذن استلام ← فاتورة ← دفعة، مع المرتجعات وأعمار ذمم الموردين.": "Purchase order → goods receipt → invoice → payment, with returns and supplier aging.",
  "دورة بيع كاملة": "Full sales cycle",
  "أمر بيع ← تسليم ← فاتورة ← تحصيل، مع المرتجعات وأعمار ذمم العملاء.": "Sales order → delivery → invoice → collection, with returns and customer aging.",
  "اربط حساب أمازون واستورد الطلبات والتسويات والمرتجعات والرسوم — وكل عملية تترحّل لمخزونك وحساباتك تلقائياً. (نون قريبًا)": "Connect your Amazon account and import orders, settlements, returns and fees — every transaction posts to your inventory and accounts automatically. (Noon coming soon)",
  "لوحة تحكم لحظية": "Real-time dashboard",
  "الأرباح والنقدية والذمم وقيمة المخزون — صورة كاملة لتجارتك في شاشة واحدة.": "Profit, cash, receivables and inventory value — a full picture of your business on one screen.",
  "عربي بالكامل": "Arabic and English",
  "واجهة RTL، أرقام وتواريخ واضحة، ومصطلحات محاسبية صحيحة.": "A full Arabic RTL interface or English, clear numbers and dates, and correct accounting terms.",
  "متّصل فعلاً": "Truly connected",
  "مش أدوات ملزوقة — المخزون والمحاسبة والمبيعات كيان واحد.": "Not tools stuck together — inventory, accounting and sales are one thing.",
