  "خصوصيتك وأمان بياناتك أولوية عندنا. توضّح هذه السياسة البيانات التي يجمعها نظام SellerCtrl وكيف نستخدمها ونحميها. باستخدامك للنظام فأنت توافق على ما ورد في هذه الصفحة.": "Your privacy and the security of your data are a priority for us. This policy explains what data SellerCtrl collects and how we use and protect it. By using the system, you agree to what's set out on this page.",
