  "كل عملية مرتبطة بنفس بيانات النظام وصلاحيات المستخدم. المسودات والترحيل يبقون خطوات منفصلة وواضحة.": "Every action uses the same system data and user permissions. Drafts and posting stay separate, clear steps.",
